/*
`E_q` from connection(`$q_g$`,`$q_h$`,`$m_g$`,`$m_h$`,`$\angle$`,`$λ_{q,1}$`,`$λ_{q,2}$`,t)
`E_a` from anchor(`$λ_{a,1}$`,`$λ_{a,2}$`,q,`$q_a$`,m,`$m_a$`, `$\angle$`)
`E_n` from notchlimit(`$δ^{(−)}$`,`$δ^{(+)}$`,`$β_q$`,`$β^{(−)}$`,`$β^{(+)}$`)
`E_p` from penalty(μ, ε, `$β_q$`)
E = `E_r` + `E_q` + `E_a` + `E_n` + `E_p`
where
`E_r` ∈ ℝ:the internal energy of the rods
where
`$q_g$` ∈ ℝ^n: point
`$q_h$` ∈ ℝ^n: point
`$m_g$` ∈ ℝ^n : the material vectors of $g$
`$m_h$` ∈ ℝ^n : the material vectors at $h$
`$\angle$` ∈ ℝ^n, ℝ^n -> ℝ^n
`$λ_{q,1}$` ∈ ℝ: the constraint weights for the position
`$λ_{q,2}$` ∈ ℝ: the constraint weights for the direction
t ∈ ℝ : offset
where
`$λ_{a,1}$` ∈ ℝ: weight
`$λ_{a,2}$` ∈ ℝ: weight
q ∈ ℝ^n 
`$q_a$` ∈ ℝ^n 
m ∈ ℝ^n 
`$m_a$` ∈ ℝ^n 
where
`$δ^{(−)}$` ∈ ℝ
`$δ^{(+)}$` ∈ ℝ
`$β_q$` ∈ ℝ :  barycentric coordinates 
`$β^{(−)}$` ∈ ℝ : the barycentric coordinates of the notch bounds on their corresponding edges
`$β^{(+)}$` ∈ ℝ : the barycentric coordinates of the notch bounds on their corresponding edges
where
μ ∈ ℝ: a weighting parameter
ε ∈ ℝ: denoting how far $q$ is allowed to move past the end of the edge

*/
#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>
#include "type_helper.h"

using namespace iheartmesh;
struct heartlib {
    using DT____ = double;
    using MatrixD____ = Eigen::MatrixXd;
    using VectorD____ = Eigen::VectorXd;
    DT____ E;
    DT____ E_q;
    DT____ E_a;
    DT____ E_n;
    DT____ E_p;

    struct connection {
        using DT = double;
        using MatrixD = Eigen::MatrixXd;
        using VectorD = Eigen::VectorXd;
        DT E_q;
        connection(
            const Eigen::VectorXd & q_g,
            const Eigen::VectorXd & q_h,
            const Eigen::VectorXd & m_g,
            const Eigen::VectorXd & m_h,
            const std::function<Eigen::VectorXd(Eigen::VectorXd, Eigen::VectorXd)> & angle,
            const double & λ_q_comma_1,
            const double & λ_q_comma_2,
            const double & t)
        {
            const long n = q_g.size();
            assert( q_h.size() == n );
            assert( m_g.size() == n );
            assert( m_h.size() == n );
            // E_q = λ_q_comma_1||q_g-q_h+tm_g||^2 + λ_q_comma_1||q_h-q_g+tm_h||^2 + λ_q_comma_2||angle(m_g,m_h)||^2
            E_q = λ_q_comma_1 * pow((q_g - q_h + t * m_g).template lpNorm<2>(), 2) + λ_q_comma_1 * pow((q_h - q_g + t * m_h).template lpNorm<2>(), 2) + λ_q_comma_2 * pow((angle((m_g).eval(), (m_h).eval())).template lpNorm<2>(), 2);
        }
    };
    struct anchor {
        using DT_ = double;
        using MatrixD_ = Eigen::MatrixXd;
        using VectorD_ = Eigen::VectorXd;
        DT_ E_a;
        anchor(
            const double & λ_a_comma_1,
            const double & λ_a_comma_2,
            const Eigen::VectorXd & q,
            const Eigen::VectorXd & q_a,
            const Eigen::VectorXd & m,
            const Eigen::VectorXd & m_a,
            const std::function<Eigen::VectorXd(Eigen::VectorXd, Eigen::VectorXd)> & angle)
        {
            const long n = q.size();
            assert( q_a.size() == n );
            assert( m.size() == n );
            assert( m_a.size() == n );
            // E_a = λ_a_comma_1||q-q_a||^2 + λ_a_comma_2||angle(m,m_a)||^2
            E_a = λ_a_comma_1 * pow((q - q_a).template lpNorm<2>(), 2) + λ_a_comma_2 * pow((angle((m).eval(), (m_a).eval())).template lpNorm<2>(), 2);
        }
    };
    struct notchlimit {
        using DT__ = double;
        using MatrixD__ = Eigen::MatrixXd;
        using VectorD__ = Eigen::VectorXd;
        DT__ E_n;
        notchlimit(
            const double & δ_circumflex_accent_minus_sign,
            const double & δ_circumflex_accent_plus_sign,
            const double & β_q,
            const double & β_circumflex_accent_minus_sign,
            const double & β_circumflex_accent_plus_sign)
        {

            // E_n = δ_circumflex_accent_minus_sign(1/10 log((β_q-β_circumflex_accent_minus_sign)))^2 + δ_circumflex_accent_plus_sign(1/10 log((β_circumflex_accent_plus_sign-β_q)))^2
            E_n = δ_circumflex_accent_minus_sign * pow((1 / DT__(10) * log((β_q - β_circumflex_accent_minus_sign))), 2) + δ_circumflex_accent_plus_sign * pow((1 / DT__(10) * log((β_circumflex_accent_plus_sign - β_q))), 2);
        }
    };
    struct penalty {
        using DT___ = double;
        using MatrixD___ = Eigen::MatrixXd;
        using VectorD___ = Eigen::VectorXd;
        DT___ E_p;
        penalty(
            const double & μ,
            const double & ε,
            const double & β_q)
        {

            // E_p = (μ log((ε + β_q)))^2 + (μ log((ε + 1 - β_q)))^2
            E_p = pow((μ * log((ε + β_q))), 2) + pow((μ * log((ε + 1 - β_q))), 2);
        }
    };
    connection _connection;
    anchor _anchor;
    notchlimit _notchlimit;
    penalty _penalty;
    heartlib(
        const double & E_r,
        const Eigen::VectorXd & q_g,
        const Eigen::VectorXd & q_h,
        const Eigen::VectorXd & m_g,
        const Eigen::VectorXd & m_h,
        const std::function<Eigen::VectorXd(Eigen::VectorXd, Eigen::VectorXd)> & angle,
        const double & λ_q_comma_1,
        const double & λ_q_comma_2,
        const double & t,
        const double & λ_a_comma_1,
        const double & λ_a_comma_2,
        const Eigen::VectorXd & q,
        const Eigen::VectorXd & q_a,
        const Eigen::VectorXd & m,
        const Eigen::VectorXd & m_a,
        const double & δ_circumflex_accent_minus_sign,
        const double & δ_circumflex_accent_plus_sign,
        const double & β_q,
        const double & β_circumflex_accent_minus_sign,
        const double & β_circumflex_accent_plus_sign,
        const double & μ,
        const double & ε)
    :
    _connection(q_g, q_h, m_g, m_h, angle, λ_q_comma_1, λ_q_comma_2, t),
    _anchor(λ_a_comma_1, λ_a_comma_2, q, q_a, m, m_a, angle),
    _notchlimit(δ_circumflex_accent_minus_sign, δ_circumflex_accent_plus_sign, β_q, β_circumflex_accent_minus_sign, β_circumflex_accent_plus_sign),
    _penalty(μ, ε, β_q)
    {
        const long n = q_g.size();
        assert( q_h.size() == n );
        assert( m_g.size() == n );
        assert( m_h.size() == n );
        assert( q.size() == n );
        assert( q_a.size() == n );
        assert( m.size() == n );
        assert( m_a.size() == n );
        E_q = _connection.E_q;
        E_a = _anchor.E_a;
        E_n = _notchlimit.E_n;
        E_p = _penalty.E_p;
        // E = `E_r` + `E_q` + `E_a` + `E_n` + `E_p`
        E = E_r + E_q + E_a + E_n + E_p;
    }
};

